package shop

import (
	"encoding/json"
	"fmt"
	"net/http"
)

// healthResponse represents the response structure for the health check endpoint.
type healthResponse struct {
	Data any `json:"data"`
}

// healthRoutes registers the health check endpoint.
func (s *Server) healthRoutes(mux *http.ServeMux) {
	mux.HandleFunc("GET /healthz", s.handleHealth)
}

// handleHealth responds with a JSON object indicating the health status and counts of stored items.
func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeError(w, http.StatusMethodNotAllowed, codeBadQuery, "only GET requests are allowed for health check")
		return
	}

	usersCount := len(s.users.List())
	productsCount := len(s.products.List())
	ordersCount := len(s.orders.List())

	response := healthResponse{
		Data: map[string]int{
			"status":  "ok",
			"users":   usersCount,
			"products": productsCount,
			"orders":  ordersCount,
		},
	}

	writeJSON(w, http.StatusOK, response)
}

