		{name: "single item", orders: []Order{{ID: "7", UserID: "u7", Items: []OrderItem{{ProductID: "p7", Quantity: 4}}}}, expected: []Order{{ID: "7", UserID: "u7", Items: []OrderItem{{ProductID: "p7", Quantity: 4}}}}},
