			writeJSON(w, http.StatusOK, filtered)
		} else {
			// Filter products with zero stock
			var filtered []Product
			for _, p := range s.products.List() {
				if p.Stock == 0 {
					filtered = append(filtered, p)
				}
			}
			slices.SortFunc(filtered, func(a, b Product) int { return strings.Compare(a.ID, b.ID) })
			writeJSON(w, http.StatusOK, filtered)
		}
