func TestParsePage(t *testing.T) {
	tests := []struct {
		name    string
		query   string
		want    pageParams
		wantErr bool
	}{
		{name: "defaults", query: "", want: pageParams{Limit: defaultLimit}},
		{name: "both", query: "?limit=5&offset=10", want: pageParams{Limit: 5, Offset: 10}},
