			return validationError{fmt.Sprintf("items[%d].quantity", i), "must be at least 1"}
		}
	}
	return nil
}

func (s *Server) handleListUserOrders(w http.ResponseWriter, r *http.Request) {
	userID := r.URL.Path[1]
	user, err := s.users.Get(userID)
	if err != nil {
		if !user {
			writeNotFound(w, "user", userID)
			return
		}
		writeError(w, http.StatusUnauthorized, codeNotFound, "user not found")
		return
	}

	p, err := parsePage(r)
	if err != nil {
		writeError(w, http.StatusBadRequest, codeBadQuery, err.Error())
		return
	}

	items, info := paginate(s.orders.List(), p)
	writeList(w, items, info)
}

